import{_ as o,o as r,c,a2 as a}from"./chunks/framework.BWuWLRhz.js";const d="/architecture-zh-CN.svg",S=JSON.parse('{"title":"架构设计","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/architecture.md","filePath":"zh-CN/dev-guide/architecture.md","lastUpdated":1787473456000}'),t={name:"zh-CN/dev-guide/architecture.md"};function i(l,e,s,p,n,h){return r(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h1><p><img src="'+d+'" alt="Lertaro 架构图"></p><h2 id="进程拆分" tabindex="-1">进程拆分 <a class="header-anchor" href="#进程拆分" aria-label="Permalink to &quot;进程拆分&quot;">​</a></h2><p>Lertaro 运行为三个独立进程，按权限级别和生命周期有意拆分:</p><ul><li><strong><code>Lertaro.Service</code></strong> —— 一个以 <code>LocalSystem</code> 身份运行的 Windows 服务。它负责全部文件索引工作:读取 NTFS/ReFS 磁盘的 USN 日志与 MFT、直接遍历并监听其他本地文件系统(它们没有日志可读)、扫描并缓存网络共享，并通过命名管道回答搜索查询。在 SYSTEM 级别运行意味着它可以读取所有用户账户都被允许看到的原始卷元数据，而不需要让交互式的 App 进程获得它本不需要的提升权限。</li><li><strong><code>Lertaro.App</code></strong> —— 用户态、Session 级别的 WPF 应用:搜索窗口、设置窗口、热键处理、动作菜单/QuickLook 界面都在这里。它通过命名管道(<code>Core.Services</code> 里的 <code>SearchService</code>/ <code>UsnServicePipeServer</code>)和 Service 通信，从不直接访问磁盘索引。它自己也额外托管了一条按用户区分的管道(<code>AppSearchPipeService</code>)，让 <code>lff</code> 命令行伴侣工具(参见<a href="./../user-guide/cli.html">命令行搜索</a>) 能复用 App 已经初始化好的搜索状态——已加载的别名/插件提供方、已配置的网络盘索引——而不用一个独立的客户端进程自己重新初始化一遍。</li><li><strong><code>Lertaro.Service --hook</code></strong> —— 一个独立的小进程，专门托管低层级全局键盘钩子，这样钩子崩溃或者某个前台应用行为异常都不会连累主 App 进程。它还会加载插件的窗口集成适配器，并在自己进程里执行这些调用——见下文<a href="#插件在架构中的位置">插件在架构中的位置</a>。</li></ul><h2 id="共享的-core" tabindex="-1">共享的 Core <a class="header-anchor" href="#共享的-core" aria-label="Permalink to &quot;共享的 Core&quot;">​</a></h2><p><code>Core</code> 是一个被 Service 和 App 同时引用的类库。它包含:</p><ul><li>搜索引擎(<code>Core/SearchIndex/Fzf/*</code>)—— 一套仿照 <code>fzf</code> 命令行工具算法实现的模糊匹配引擎，配合一个查询解析器(<code>SearchQueryParser</code>)处理盘符定向和路径模式搜索。</li><li>运行时索引(<code>Core/IndexV2/*</code>)—— 由 USN/MFT 读取结果构建的内存映射列式快照格式，配合一个内存中的增量覆盖层记录快照之后的变更。</li><li>IPC 契约(<code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等)—— App 和 Service 两边完全共用同一份定义，保证双方对线路格式的理解始终一致。</li><li><code>Logger</code> —— 写入各进程独立的日志文件(<code>service.log</code>、<code>app.log</code>、<code>hook.log</code>)，都可以在 App 的设置 → 运行状态 日志查看器里读取(但不是都能直接写入)。</li></ul><h2 id="插件在架构中的位置" tabindex="-1">插件在架构中的位置 <a class="header-anchor" href="#插件在架构中的位置" aria-label="Permalink to &quot;插件在架构中的位置&quot;">​</a></h2><p>插件是引用 <code>PluginSdk</code> 的 <code>.dll</code> 程序集，由 App 进程加载(见<a href="./getting-started.html">快速上手</a>和<a href="./packaging.html">打包与发布</a>)。Lertaro 自带内置插件作为一等公民示例——<code>Lertaro.Plugins.CoreExtensions</code>(内置文件动作与 Shell 右键菜单集成)、<code>Lertaro.Plugins.PinyinAlias</code>(中文文件名拼音别名)以及 <code>Lertaro.Plugins.FlowLauncherBridge</code>(桥接 C#、Python 3.12、Node.js v20 LTS 及可执行文件格式的第三方 Flow Launcher 插件并提供纯净隔离运行环境)——参见<a href="./examples.html">插件示例</a>了解原生插件的详细走读。</p><p>插件从不直接和 Service 通信;它们通过插件 SDK 参考里记录的接口和 App 交互，如果需要索引自定义目录，则通过 <code>DirectoryIndexerService</code> 代为向 Service 转发请求。</p><p>窗口集成类适配器是&quot;只在 App 里跑&quot;这条规则的唯一例外: <a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a> 的实现会被再加载一份到 Hook 进程里，它们的调用实际在 Hook 进程里执行，而不是在 App 里。这也是为什么 Lertaro 能操作一个以管理员身份运行的文件资源管理器/文件对话框/第三方文件管理器窗口——即使 App 本身从来不提权:Windows 不允许低权限进程向高权限进程发送输入，所以这类调用必须从一个和目标窗口权限级别相同的进程发起。</p>',12)])])}const g=o(t,[["render",i]]);export{S as __pageData,g as default};
